#include <aibs/initial_view.hpp>
#include <aibs/warm_opening.hpp>
#include <aibs/content_authoring.hpp>
#include <algorithm>
#include <filesystem>
#include <iostream>
#include <stdexcept>
using namespace aibs;
namespace fs=std::filesystem;
namespace {unsigned checks=0;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}const ContentAuthoringRow& settings(const std::vector<ContentAuthoringRow>& rows){const auto found=std::find_if(rows.begin(),rows.end(),[](const auto& row){return row.type_id=="authoring.ChapterSettings";});if(found==rows.end())throw std::runtime_error("Settings row missing");return *found;}}
int wmain(int argc,wchar_t** argv){try{
 if(argc!=2||!fs::is_directory(argv[1]))throw std::invalid_argument("Existing owned evidence parent required");const fs::path out=fs::path(argv[1])/new_uuid();fs::create_directory(out);fs::create_directory(out/"packs");
 CreatorSession source(first_boot_schema(),"initial-view-authoring","main");check(seed_first_boot(source).ok,"Seed failed");const auto legacy=FirstBootContent::from_template(source);auto d=make_warm_opening_definition(source,{});const auto controller=std::find_if(d.fixtures.begin(),d.fixtures.end(),[](const auto& f){return f.object.name=="Controller and turning";});check(controller!=d.fixtures.end(),"Controller fixture missing");const auto id=controller->object.persistent_id;d.hints[std::string(first_boot_initial_view_key)]=id;
 const auto content=FirstBootContent::create(d);check(content.definition().hints.size()==31,"Explicit framing should consume one of32 slots");
 const auto rows=content_authoring_rows(content);check(std::get<std::string>(settings(rows).fields.at("hint.view.initial_target"))==id,"Modern authoring did not expose initial target");const auto old_rows=content_authoring_rows(legacy);check(!settings(old_rows).fields.contains("hint.view.initial_target"),"Legacy row format changed");
 ContentAuthoringHost host(content,"initial-view-authoring","main");host.bind_asset_store(out/"packs");
 const auto request=[&](std::vector<ContentEdit> edits){const auto snapshot=host.snapshot();return ContentEditRequest{new_uuid(),snapshot->revision,snapshot->content.fingerprint(),"Initial view contract",std::move(edits)};};
 auto before=host.snapshot();const auto rejected=host.preview(before->scope,request({ContentEraseFixture{id}}));check(rejected.status==ContentAuthoringStatus::rejected,"Erasing a bound target silently cleared view intent");check(host.snapshot()->content.fingerprint()==before->content.fingerprint(),"Rejected erase mutated content");
 const auto unbound=host.preview(before->scope,request({ContentSetField{id,"inspection_text",std::string{}},ContentSetField{id,"inspection_source",std::string{}},ContentSetField{id,"inspection_action",std::string{}}}));check(unbound.status==ContentAuthoringStatus::rejected,"Unbinding active inspection target was accepted");
 auto clear=request({ContentSetField{d.definition_id,"hint.view.initial_target",std::string{}}});auto prepared=host.preview(host.snapshot()->scope,clear);check(prepared.status==ContentAuthoringStatus::prepared&&host.apply(prepared.change).status==ContentAuthoringStatus::applied,"Explicit clear failed");check(!host.snapshot()->content.definition().hints.contains(std::string(first_boot_initial_view_key)),"Clear serialized an empty target instead of erasing");const auto cleared_rows=content_authoring_rows(host.snapshot()->content);check(std::get<std::string>(settings(cleared_rows).fields.at("hint.view.initial_target")).empty(),"Modern cleared field disappeared from observation");
 auto assign=request({ContentSetField{d.definition_id,"hint.view.initial_target",id}});prepared=host.preview(host.snapshot()->scope,assign);check(prepared.status==ContentAuthoringStatus::prepared&&host.apply(prepared.change).status==ContentAuthoringStatus::applied,"Reassign failed");
 const auto snapshot=host.snapshot();auto grouped=request({ContentEraseFixture{id},ContentSetField{d.definition_id,"hint.view.initial_target",std::string{}}});prepared=host.preview(snapshot->scope,grouped);check(prepared.status==ContentAuthoringStatus::prepared&&host.apply(prepared.change).status==ContentAuthoringStatus::applied,"Atomic erase plus clear was rejected");check(!first_boot_initial_view(host.snapshot()->content.definition()),"Grouped clear retained binding");
 auto history=[&](bool redo){const auto s=host.snapshot();return host.travel(s->scope,{new_uuid(),s->revision,s->content.fingerprint(),redo});};check(history(false).status==ContentAuthoringStatus::undone,"Undo failed");check(first_boot_initial_view(host.snapshot()->content.definition())->target_id==id,"Undo did not restore full target/inspection dependency");check(history(true).status==ContentAuthoringStatus::redone&&!first_boot_initial_view(host.snapshot()->content.definition()),"Redo did not restore explicit deletion/clear");
 check(host.save(out/"chapter.aiba").status==ContentAuthoringStatus::saved,"Authoring save failed");auto reopened=ContentAuthoringHost::open(out/"chapter.aiba","initial-view-authoring","main");check(!first_boot_initial_view(reopened.snapshot()->content.definition()),"New owner lost clear state");check(reopened.snapshot()->content.definition().format_version==3,"Save downgraded AIBD3");
 std::cout<<checks<<" scoped initial-view content/authoring checks passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
